mapper.insert:
INSERT INTO
quiz_room_member(member_id, room_id, is_host)
VALUES(#{memberId}, #{roomId}, #{isHost});

mapper.select:
SELECT COUNT(*)
FROM quiz_room
WHERE room_id = #{roomId}

SELECT COUNT(1)
FROM quiz_room_member
WHERE member_id = #{memberId}

mapper.delete:
DELETE FROM quiz_room_member
WHERE room_id = #{roomId}
AND member_id = #{memberId}
